<x-layouts.app heading="User management"><div class="toolbar"><form class="filters"><input name="search" value="{{ request('search') }}" placeholder="Search name or email"><select name="status"><option value="">All accounts</option><option value="1">Active</option><option value="0">Inactive</option></select><button class="btn">Filter</button></form><a class="btn primary" href="{{ route('users.create') }}">Add user</a></div><article class="panel"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last sign-in</th><th></th></tr></thead><tbody>@foreach($users as $user)<tr><td><b>{{ $user->name }}</b><small>{{ $user->email }}</small></td><td>{{ $user->roles->pluck('label')->join(', ') }}</td><td><span class="status {{ $user->is_active?'active':'inactive' }}">{{ $user->is_active?'Active':'Inactive' }}</span></td><td>{{ $user->last_login_at?->diffForHumans() ?? 'Never' }}</td><td><a href="{{ route('users.edit',$user) }}">Edit</a></td></tr>@endforeach</tbody></table>{{ $users->links() }}</article></x-layouts.app>
